def match(orders):
    trades = []

    # Order book: {price: [(arrival_time, id, remaining_qty), ...]}
    buy_book = {}  # keyed by price, highest to lowest
    sell_book = {}  # keyed by price, lowest to highest

    # Track order info for cancellations and matching
    order_info = {}  # id -> (side, price, original_arrival_time, is_cancelled)
    arrival_time_counter = 0

    for order in orders:
        arrival_time_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_info:
                side, price, arr_time, is_cancelled = order_info[order_id]
                if not is_cancelled:
                    # Mark as cancelled and remove from book
                    order_info[order_id] = (side, price, arr_time, True)
                    if side == 'buy':
                        if price in buy_book:
                            buy_book[price] = [(t, oid, qty) for t, oid, qty in buy_book[price] if oid != order_id]
                            if not buy_book[price]:
                                del buy_book[price]
                    else:  # sell
                        if price in sell_book:
                            sell_book[price] = [(t, oid, qty) for t, oid, qty in sell_book[price] if oid != order_id]
                            if not sell_book[price]:
                                del sell_book[price]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[3] if order_type == 'market' else order[4]
        price = order[3] if order_type != 'market' else None

        order_info[order_id] = (side, price, arrival_time_counter, False)
        remaining_qty = qty

        if side == 'buy':
            # Match against sell orders: lowest price first, then earliest arrived
            sell_prices = sorted(sell_book.keys())
            for sell_price in sell_prices:
                if order_type != 'market' and sell_price > price:
                    break

                while remaining_qty > 0 and sell_book.get(sell_price):
                    arr_time, sell_id, sell_qty = sell_book[sell_price][0]

                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    remaining_qty -= trade_qty
                    sell_qty -= trade_qty

                    if sell_qty == 0:
                        sell_book[sell_price].pop(0)
                        if not sell_book[sell_price]:
                            del sell_book[sell_price]
                    else:
                        sell_book[sell_price][0] = (arr_time, sell_id, sell_qty)

        else:  # sell
            # Match against buy orders: highest price first, then earliest arrived
            buy_prices = sorted(buy_book.keys(), reverse=True)
            for buy_price in buy_prices:
                if order_type != 'market' and buy_price < price:
                    break

                while remaining_qty > 0 and buy_book.get(buy_price):
                    arr_time, buy_id, buy_qty = buy_book[buy_price][0]

                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    remaining_qty -= trade_qty
                    buy_qty -= trade_qty

                    if buy_qty == 0:
                        buy_book[buy_price].pop(0)
                        if not buy_book[buy_price]:
                            del buy_book[buy_price]
                    else:
                        buy_book[buy_price][0] = (arr_time, buy_id, buy_qty)

        # Add remaining quantity to book (only for limit orders)
        if remaining_qty > 0 and order_type == 'limit':
            if side == 'buy':
                if price not in buy_book:
                    buy_book[price] = []
                buy_book[price].append((arrival_time_counter, order_id, remaining_qty))
            else:  # sell
                if price not in sell_book:
                    sell_book[price] = []
                sell_book[price].append((arrival_time_counter, order_id, remaining_qty))

    return trades

